mapper.select:
SELECT r.`trade_date` AS tradeDate, r.`asset_code` AS assetCode, r.`return_rate` AS returnRate, s.`stage` AS stage FROM `stock_returns` r LEFT JOIN `stock_historical_stage` s ON r.`trade_date` = s.`trade_date`
AND r.`asset_code` IN
#{code}
AND r.`trade_date` >= #{startDate}
AND r.`trade_date` <= #{endDate}
ORDER BY r.`trade_date` ASC, r.`asset_code` ASC
